/**
 * Multi-select archive. Ids are de-duplicated in request order. An id that
 * names no issue of this org, or an already-archived one, is skipped and left
 * untouched. Every other issue must pass the same `issue:archive` check as a
 * single archive, and that is settled for all of them before anything is
 * written, so one denial archives nothing and publishes nothing.
 */
export async function bulkArchiveIssues(
  actor: Actor,
  input: BulkArchiveIssuesInput,
): Promise<{ archived: readonly IssueId[]; skipped: readonly IssueId[] }> {
  assertOrgScope(actor, input.orgId);

  const requested = [...new Set(input.issueIds)];
  const found = new Map<IssueId, Issue>(
    (await issueRepo.findIssuesByIds(input.orgId, requested)).map((issue) => [
      issue.id,
      issue,
    ]),
  );

  const skipped: IssueId[] = [];
  const toArchive: Issue[] = [];
  for (const issueId of requested) {
    const issue = found.get(issueId);
    if (issue === undefined || isArchived(issue)) {
      skipped.push(issueId);
      continue;
    }
    assertCan(actor, "issue:archive", issueResource(issue));
    toArchive.push(issue);
  }

  const archived: IssueId[] = [];
  for (const issue of toArchive) {
    const row = await issueRepo.archiveIssue(input.orgId, issue.id);

    await emit("issue.archived", {
      ...actorEnvelope(actor),
      issueId: row.id,
      projectId: row.projectId,
    });
    archived.push(row.id);
  }

  return { archived, skipped };
}

